381	/* ---- The collapsed tile ------------------------------------------------- *
382	 * Same size and same hairline as a claim's tile, but drawn with a dashed line,
383	 * because it is not a claim — it is the count of the ones a column had no room
384	 * for. */
385	
386	.tile--overflow {
387	  justify-content: center;
388	  text-align: center;
389	}
390	
391	.tile--overflow .tile__outline rect {
392	  fill: none;
393	  stroke: var(--hairline);
394	  stroke-width: 1;
395	}
396	
397	.tile__overflow-count {
398	  margin: 0;
399	  font-family: var(--font-mono);
400	  font-variant-numeric: tabular-nums;
401	  font-size: var(--text-lg);
402	  font-weight: var(--weight-medium);
403	  color: var(--text);
404	}
405	
406	.tile__overflow-line {
407	  margin: 0;
408	  font-size: var(--text-sm);
409	  color: var(--text-muted);
410	  text-wrap: pretty;
411	}
412	
413	/* ---- Far out: the summary ---------------------------------------------- *
414	 * Zoomed out past the threshold a tile changes what it draws rather than
415	 * shrinking what it draws. It keeps the claim and the three readings and drops
416	 * everything else — the kind, the date, the reason a slot is empty, the
417	 * clippings — and it sets every word it keeps in the largest of the three type
418	 * sizes. That last part is what makes the eleven-pixel floor true: twenty-two
419	 * pixels at the furthest the map zooms out, which is half, is eleven pixels on
420	 * the reader's screen, and the map does not zoom out past half.
421	 *
422	 * The three readings stop being a three-up row out here and become three lines,
423	 * each one read the way it would be said: the owner, the number, the range. A
424	 * range is never dropped, at any zoom. */
425	
426	.tile[data-detail="summary"] {
427	  gap: var(--space-2);
428	  justify-content: center;
429	}
430	
431	.tile[data-detail="summary"] .tile__header,
432	.tile[data-detail="summary"] .tile__foot {
433	  display: none;
434	}
435	
436	.tile[data-detail="summary"] .tile__claim {
437	  font-size: var(--text-lg);
438	  line-height: 1.25;
439	  font-weight: var(--weight-medium);
440	  /* Two lines out here whatever the full tile shows: the summary is a glance,
441	   * not a read. */
442	  -webkit-line-clamp: 2;
443	  line-clamp: 2;
444	}
445	
446	.tile[data-detail="summary"] .tile__beliefs {
447	  /* One line per owner, stacked. The row above makes its columns from the
448	   * chips themselves, so out here the flow has to be turned back to rows as
449	   * well — otherwise a second chip takes a column of its own beside the first
450	   * and the two lines are printed over each other (Kent saw exactly that on the
451	   * one tile holding a venue's number, 2026-09-22). */
452	  grid-auto-flow: row;
453	  grid-template-columns: minmax(0, 1fr);
454	  row-gap: var(--space-hair);
455	}
456	
457	.tile[data-detail="summary"] .tile__beliefs > * + * {
458	  padding-left: 0;
459	  border-left: none;
460	}
461	
462	.tile[data-detail="summary"] .belief-chip__face {
463	  /* The owner's column is measured in this line's own type size, so the line
464	   * has to be set at that size before the column is worked out. */
465	  font-size: var(--text-lg);
466	  grid-template-rows: auto;
467	  /* The owner's column is as wide as the longest owner, *market*, and no wider.
468	   * It was a fifth wider than that, and the line then ran past the row by 5
469	   * pixels on an ordinary tile and by 17 on the two whose outline cuts into one
470	   * side — far enough that the end of the range was cut off (measured on the
471	   * stored example at the furthest zoom, 2026-09-22). */
472	  grid-template-columns: 3.5em auto auto;
473	  grid-auto-flow: column;
474	  justify-items: start;
475	  align-items: baseline;
476	  column-gap: var(--space-1);
477	  width: 100%;
478	}
479	
480	.tile[data-detail="summary"] .belief-chip__owner,
481	.tile[data-detail="summary"] .belief-chip__reading,
482	.tile[data-detail="summary"] .belief-chip__under {
483	  font-size: var(--text-lg);
484	  line-height: 1.25;
485	  min-height: 0;
486	}
487	
488	/* ---- The ports ---------------------------------------------------------- *
489	 * One group of inputs on the left, one group of outputs on the right, and two
490	 * sockets in each: an arrow that fires once and stays fired lands in a
491	 * different socket from one that has to keep holding. A single tick for the
492	 * first, a double tick for the second — the same doubling the wire itself will
493	 * use, so the socket and the wire say the same thing.
494	 *
495	 * **Where a port sits is not here.** Its box — left, top, width and height —
496	 * depends on how tall its tile turned out to be, and the drawing library is
497	 * handed those same four numbers so that it can draw a wire before it has
498	 * measured anything. So `graph/ports.ts` works them out and `Tile.tsx` writes
499	 * them onto the element; a second copy in a stylesheet is a second thing to
500	 * keep in step, and it would not be kept. What is left below is only how a port
501	 * looks — which is an override of the drawing library's own handle styling, a
502	 * blue circle, because nothing in this product looks like the library it was
503	 * built with.
504	 *
505	 * Each bar below is measured in pixels down from the top of the port, and the
506	 * last stop of each run is written `100%` — the foot of the port, whatever the
507	 * port's height turns out to be. Writing that height here as a number would be
508	 * the second copy this section exists to do without. */
509	
510	.tile__port.react-flow__handle {
511	  min-width: 0;
512	  min-height: 0;
513	  border: none;
514	  border-radius: 0;
515	  background: none;
516	}
517	
518	/* One bar: fires once, and stays fired. Shifted down by its own thickness, and
519	 * repeating, so the single bar lands in the middle of the port. */
520	.tile__port--trigger {
521	  background: linear-gradient(var(--text-muted) 0 2px, transparent 2px 100%);
522	  background-position: 0 2px;
523	}
524	
525	/* Two bars: holds only while its cause holds. */
526	.tile__port--sustain {
527	  background: linear-gradient(
528	    var(--text-muted) 0 2px,
529	    transparent 2px 4px,
530	    var(--text-muted) 4px 100%
531	  );
532	}
