  font-weight: var(--weight-medium);
  /* Two lines out here whatever the full tile shows: the summary is a glance,
   * not a read. */
  -webkit-line-clamp: 2;
  line-clamp: 2;
}

.tile[data-detail="summary"] .tile__beliefs {
