.tile__claim,
.tile__beliefs,
.tile__foot {
  flex: none;
}

/* The drawn outline: the fill and the one-pixel line, in the shape that says
 * what kind of claim this is. Sits behind everything in the tile, and takes no
 * clicks. */
.tile__outline {
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
}

.tile__outline path {
  fill: var(--surface-raised);
  stroke: var(--hairline);
  stroke-width: 1;
}

/* Two of the four outlines cut into the tile on one side — the hypothesis comes
 * to a point on the left, the dead end is notched on the right — so those two
 * tiles hold their words a step further from that edge. Nothing is ever drawn
 * across a word. */
.tile[data-kind="hypothesis"] {
  padding-left: var(--space-3);
}

.tile[data-kind="not_tradeable"] {
  padding-right: var(--space-3);
}

/* The claim the reader started from is the one thing on the map that did not
 * come from the model, so its outline is drawn in the accent rather than in the
 * hairline. The shape already says it is the hypothesis; this only makes the
 * eye land there first. */
.tile[data-hypothesis="yes"] .tile__outline path {
  stroke: var(--accent);
}

/* ---- The header: what kind of claim, and when it settles ---------------- */

.tile__header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--space-1);
  font-size: var(--text-sm);
  color: var(--text-muted);
  min-width: 0;
}

.tile__kind {
  font-weight: var(--weight-medium);
  letter-spacing: 0.04em;
  white-space: nowrap;
}

.tile__resolves {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

/* ---- The claim ---------------------------------------------------------- *
 * As many lines as the tile was built to hold — at most three — and then it
 * stops. The number comes from the same place the tile's height came from, so
 * the claim stops exactly where the box ends and never a line later. The stop
 * is by line rather than by character, so a word is never cut in half to save a
 * few pixels; the rest of the sentence lives in the panel beside the map. */

.tile__claim {
  margin: 0;
  font-size: var(--text-md);
  line-height: 1.35;
  color: var(--text);
  text-wrap: pretty;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: var(--tile-claim-lines, 3);
  line-clamp: var(--tile-claim-lines, 3);
  overflow: hidden;
}

/* ---- The beliefs -------------------------------------------------------- *
 * Side by side, equal widths, with a hairline between them. One column per
 * owner who has something to say: the model always, and the reader and a venue
 * where they hold a number. They are never merged into one number — the shape
 * of the row is the argument — and a column with nothing in it is not drawn.
 *
 * The columns are made by the chips rather than declared as three, so the row
 * shares its whole width between whichever of them are there: one chip fills
 * the tile, two take half each, three take a third each exactly as before.
 * **The tile does not change size either way.** Its height and its width are
 * written on its own box from `geometry.ts`, which reserves the same rail
 * whatever the chips hold — so a number arriving later widens the survivors and
 * re-lays out nothing. */

.tile__beliefs {
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: minmax(0, 1fr);
  column-gap: var(--space-1);
  padding-top: var(--space-1);
  border-top: 1px solid var(--hairline);
}

.tile__beliefs > * + * {
  padding-left: var(--space-1);
  border-left: 1px solid var(--hairline);
}

/* Why a slot has no number, in the map's own words. Two lines, then it stops —
 * the whole sentence is on the chip's shelf and, later, in the panel. */
.tile__absence {
  margin: 0;
  font-size: var(--text-sm);
  color: var(--text-muted);
  line-height: 1.35;
  text-wrap: pretty;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  line-clamp: 2;
  overflow: hidden;
}

/* The foot of the tile: why a slot has no number, the evidence clippings, and
 * the badges. Pushed to the bottom edge as one block, so that every tile in a
 * column has its claim on the same line and its clippings on the same line. */
.tile__foot {
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
  margin-top: auto;
}

/* ---- Evidence clippings ------------------------------------------------- *
 * A letter standing for the publication, a sign saying which way the item cuts,
 * and one line of what it says. The letter comes from the host name in the
 * source's own address rather than from the publication's icon: an icon is a
 * request to somebody else's server, and this app draws its first frame without
 * making one. */

.tile__clippings {
  margin: 0;
  padding: 0;
  list-style: none;
  display: grid;
  row-gap: var(--space-hair);
  align-content: end;
}

.tile__clipping {
  display: grid;
  grid-template-columns: auto auto minmax(0, 1fr);

