/**
 * Throwaway. Measures every far-away tile's belief lines against its row and its
 * box, in four states, and photographs each. Run with `node measure.mjs <tag>`.
 */
import { chromium } from "/Users/kentgang/git3/katalyst-wt/feat-04-the-quieter-tile/frontend/node_modules/playwright/index.mjs";

const HERE = "/Users/kentgang/git3/katalyst/plans/logs/04c/far";
const TAG = process.argv[2] ?? "run";
const APP = "http://localhost:5147";
const A_PIXEL = 1;

const READ = () =>
  [...document.querySelectorAll(".react-flow__node .tile")].map((tile) => {
    const box = tile.getBoundingClientRect();
    const row = tile.querySelector(".tile__beliefs")?.getBoundingClientRect() ?? null;
    const claimEl = tile.querySelector(".tile__claim");
    const claimBox = claimEl?.getBoundingClientRect() ?? null;
    const lines = [...tile.querySelectorAll(".belief-chip")].map((chip) => {
      const drawn = [...chip.querySelectorAll(".belief-chip__face *")]
        .filter((p) => p.children.length === 0 && p.textContent?.trim())
        .map((p) => p.getBoundingClientRect())
        .filter((b) => b.width > 2 && b.height > 2);
      const faceBox = chip.querySelector(".belief-chip__face")?.getBoundingClientRect() ?? null;
      return {
        owner: chip.getAttribute("data-owner"),
        text: [...chip.querySelectorAll(".belief-chip__face *")]
          .filter((p) => p.children.length === 0 && p.textContent?.trim())
          .map((p) => p.textContent.trim())
          .join(" "),
        left: Math.min(...drawn.map((b) => b.left)),
        right: Math.max(...drawn.map((b) => b.right)),
        top: Math.min(...drawn.map((b) => b.top)),
        bottom: Math.max(...drawn.map((b) => b.bottom)),
        faceH: faceBox ? Math.round(faceBox.height * 10) / 10 : 0,
      };
    });
    const scale = box.width / 280;
    return {
      claim: (claimEl?.textContent ?? "").slice(0, 34),
      kind: tile.dataset.kind,
      detail: tile.dataset.detail,
      scale: Math.round(scale * 1000) / 1000,
      tileTop: box.top,
      tileBottom: box.bottom,
      tileLeft: box.left,
      tileRight: box.right,
      tileH: Math.round((box.height / scale) * 10) / 10,
      claimH: claimBox ? Math.round((claimBox.height / scale) * 10) / 10 : 0,
      rowLeft: row?.left ?? 0,
      rowRight: row?.right ?? 0,
      rowTop: row?.top ?? 0,
      rowBottom: row?.bottom ?? 0,
      lines,
    };
  });

function judge(tag, tiles) {
  const faults = [];
  let far = 0;
  let twoBelief = 0;
  let worstRight = -1e9;
  let worstBottom = -1e9;
  for (const t of tiles) {
    if (t.detail !== "summary") continue;
    far += 1;
    if (t.lines.length > 1) twoBelief += 1;
    const scale = t.scale || 1;
    for (const line of t.lines) {
      const overRight = (line.right - t.rowRight) / scale;
      const overBottom = (line.bottom - t.tileBottom) / scale;
      worstRight = Math.max(worstRight, overRight);
      worstBottom = Math.max(worstBottom, overBottom);
      if (line.right > t.rowRight + A_PIXEL)
        faults.push(
          `${tag} | "${t.claim}" [${t.kind}] ${line.owner} "${line.text}" runs ${overRight.toFixed(1)}px past its row`,
        );
      if (line.bottom > t.tileBottom + A_PIXEL)
        faults.push(
          `${tag} | "${t.claim}" [${t.kind}] ${line.owner} runs ${overBottom.toFixed(1)}px off the foot of its tile`,
        );
      if (line.left < t.rowLeft - A_PIXEL)
        faults.push(`${tag} | "${t.claim}" ${line.owner} starts left of its row`);
      if (line.top < t.tileTop - A_PIXEL)
        faults.push(`${tag} | "${t.claim}" ${line.owner} runs off the top of its tile`);
    }
    for (const [at, one] of t.lines.entries()) {
      for (const other of t.lines.slice(at + 1)) {
        const apart =
          one.right <= other.left + A_PIXEL ||
          other.right <= one.left + A_PIXEL ||
          one.bottom <= other.top + A_PIXEL ||
          other.bottom <= one.top + A_PIXEL;
        if (!apart)
          faults.push(
            `${tag} | "${t.claim}" the ${one.owner} line and the ${other.owner} line are printed over each other`,
          );
      }
    }
  }
  return { faults, far, twoBelief, worstRight, worstBottom };
}

const rows = [];

async function report(page, tag, shot) {
  const tiles = await page.evaluate(READ);
  const { faults, far, twoBelief, worstRight, worstBottom } = judge(tag, tiles);
  rows.push({ tag, far, twoBelief, worstRight, worstBottom, faults: faults.length });
  console.log(
    `\n### ${tag}  — ${far} far tiles, ${twoBelief} with two beliefs, ${faults.length} faults` +
      `\n    worst past row right: ${worstRight.toFixed(1)}px · worst past tile foot: ${worstBottom.toFixed(1)}px`,
  );
  for (const t of tiles.filter((t) => t.detail === "summary")) {
    console.log(
      `  [${(t.kind ?? "").padEnd(13)}] h=${t.tileH} claimH=${t.claimH} rowH=${(((t.rowBottom - t.rowTop) / (t.scale || 1))).toFixed(1)} "${t.claim}"`,
    );
    for (const l of t.lines)
      console.log(
        `      ${String(l.owner).padEnd(7)} faceH=${(l.faceH / (t.scale || 1)).toFixed(1)} "${l.text}" pastRow=${(((l.right - t.rowRight) / (t.scale || 1))).toFixed(1)} pastFoot=${(((l.bottom - t.tileBottom) / (t.scale || 1))).toFixed(1)}`,
      );
  }
  for (const f of faults) console.log("  RED  " + f);
  if (shot) await page.screenshot({ path: `${HERE}/${TAG}-${shot}.png` });
  return faults;
